class Solution:
    def minCost(self, nums: List[int], x: int) -> int:
        n = len(nums)
        cur = nums[:]
        ans = sum(cur)
        for t in range(1, n):
            for i in range(n):
                cur[i] = min(cur[i], nums[(i - t) % n])
            ans = min(ans, sum(cur) + t * x)
        return ans

