class Solution {
public:
    long long minCost(vector<int>& nums, int x) {
        int n = nums.size();
        vector<long long> cur(nums.begin(), nums.end());
        long long ans = accumulate(cur.begin(), cur.end(), 0LL);
        for (int t = 1; t < n; t++) {
            for (int i = 0; i < n; i++) cur[i] = min(cur[i], (long long)nums[((i - t) % n + n) % n]);
            ans = min(ans, accumulate(cur.begin(), cur.end(), 0LL) + (long long)t * x);
        }
        return ans;
    }
};

