class Solution {
    public long minCost(int[] nums, int x) {
        int n = nums.length;
        long[] cur = new long[n];
        for (int i = 0; i < n; i++) cur[i] = nums[i];
        long ans = java.util.Arrays.stream(cur).sum();
        for (int t = 1; t < n; t++) {
            for (int i = 0; i < n; i++) cur[i] = Math.min(cur[i], nums[((i - t) % n + n) % n]);
            long s = 0; for (long v : cur) s += v;
            ans = Math.min(ans, s + (long) t * x);
        }
        return ans;
    }
}

