class Solution {
    public long minCost(int[] nums, int x) {
        int n = nums.length;
        long[] best = new long[n], rot = new long[n];
        for (int i = 0; i < n; i++) { best[i] = nums[i]; rot[i] = nums[i]; }
        long ans = 0; for (long v : best) ans += v;
        for (int t = 1; t < n; t++) {
            long last = rot[n - 1];
            System.arraycopy(rot, 0, rot, 1, n - 1); rot[0] = last;
            long s = 0;
            for (int i = 0; i < n; i++) { best[i] = Math.min(best[i], rot[i]); s += best[i]; }
            ans = Math.min(ans, s + (long) t * x);
        }
        return ans;
    }
}

